async function refreshSharedInventory(id=library){const active=libraries.find(x=>x.id===id);if(!active||active.personal!==false)return;const epoch=authEpoch;const [response,bookings]=await Promise.all([client.rpc('get_shared_filaments',{shared_lib:id}),client.rpc('get_shared_bookings',{shared_lib:id})]);if(library!==id||epoch!==authEpoch)return;
 for(const r of [response,bookings])if(r.error&&r.error.code!=='PGRST202')throw r.error;
 const snapshot=bridge.snapshot(),state=withoutSharedItems(snapshot);
 bridge.apply({...state,items:response.error?snapshot.items:mergedInventory(state.items,Array.isArray(response.data)?response.data:[]),reservations:bookings.error?snapshot.reservations:mergedBookings(state.reservations,Array.isArray(bookings.data)?bookings.data:[])});updateBookings();}

